        \node[below right = 2.5cm of nw] (s) {$x\otimes  y$};
        \node[above right = 2.5cm of s] (ne) {$x\otimes {\mathopen {}\left (I\otimes  y\right )\mathclose {}}$};
        \draw[->] (nw) to node[above] {$\alpha _{x,I,y}$} (ne);
        \draw[->] (nw) to node[sloped,below] {$\rho _x\otimes  1_{y}$} (s);
        \draw[->] (ne) to node[sloped,below] {$1_{x}\otimes  \lambda _{y}$} (s);
