        \node (nw) {${\mathopen {}\left ({\mathopen {}\left (w\otimes  x\right )\mathclose {}}\otimes  y\right )\mathclose {}}\otimes  z$};
        \node[above right = 3cm of nw, xshift=1cm] (n) {${\mathopen {}\left (w\otimes  x\right )\mathclose {}}\otimes {\mathopen {}\left (y\otimes  z\right )\mathclose {}}$};
        \node[below right = 3cm of n, xshift=1cm] (ne) {$w\otimes {\mathopen {}\left (x\otimes {\mathopen {}\left (y\otimes  z\right )\mathclose {}}\right )\mathclose {}}$};
        \node[below = of nw] (sw) {${\mathopen {}\left (w\otimes {\mathopen {}\left (x\otimes  y\right )\mathclose {}}\right )\mathclose {}}\otimes  z$};
        \node[below = of ne] (se) {$w\otimes {\mathopen {}\left ({\mathopen {}\left (x\otimes  y\right )\mathclose {}}\otimes  z\right )\mathclose {}}$};
        \draw[->] (nw) to node[left] {$\alpha _{w,x,y}\otimes 1_{z}$} (sw);
        \draw[->] (sw) to node[below] {$\alpha _{w,x\otimes  y,z}$} (se);
        \draw[->] (se) to node[right] {$1_{w}\otimes \alpha _{x,y,z}$} (ne);
        \draw[->] (nw) to node[sloped,above] {$\alpha _{w\otimes  x},y,z$} (n);
        \draw[->] (n) to node[sloped,above] {$\alpha _{w,x,y\otimes  z}$} (ne);
      \end {tikzpicture}
